#!/usr/bin/env bash
# suite-managed (deploy) — regenerated by conform, do not edit by hand.
# The ONE command a developer/CI should run to (re)build this node's images.
# Wraps prebuild.sh + `docker compose build` in a fixed order so the two steps
# can never run out of sync: a bare `docker compose build` launched without
# prebuild.sh first either dies mid-install on a missing backend/vendor/<dist>
# (fresh clone, vendor/ is gitignored) or — worse — succeeds silently against a
# STALE vendor/ left over from a previous prebuild, shipping yesterday's code
# for today's image. Both failure modes were hit for real (a node's backend
# container ran unhealthy for hours before the missing prebuild step was
# found), which is why this wrapper exists instead of relying on developers to
# remember the two-command sequence from the docs.
#
# Usage: bash deploy/build.sh [--prod] [SERVICE...]   (same args `docker compose build` takes)
# After it succeeds, `docker compose up -d` picks up the fresh image — no
# `--build` there needed, and none of THIS script's vendoring is re-triggered
# by a plain `up -d`, since that never rebuilds an existing image.
set -euo pipefail
DEPLOY_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
bash "$DEPLOY_DIR/prebuild.sh"
# GIT_COMMIT feeds the backend image's .git-commit (see backend.Dockerfile):
# without it every image bakes "unknown" and a running container cannot say
# which code it carries.
export GIT_COMMIT="$(git -C "$DEPLOY_DIR/.." rev-parse --short HEAD 2>/dev/null || echo unknown)"
# compose.sh adds the node's ../.env (Life#90) and the same compose files `up`
# uses; --prod builds the production images (Life#133).
PROD=()
if [[ "${1:-}" == "--prod" ]]; then
  PROD=(--prod)
  shift
fi
exec bash "$DEPLOY_DIR/compose.sh" ${PROD[@]+"${PROD[@]}"} build --build-arg GIT_COMMIT "$@"
